def ascending_strategy(banned: set[int]) -> int:
    if not banned:
        return 0
    return max(banned) + 1

def play_game(mortal, eternity, n):
    banned = set()
    for i in range(n):
        pos = mortal(banned)
        if pos in banned:
            return False
        banned.add(eternity(banned, pos))
    return True

def verify_omega_sq(mortal, eternity, max_m=20, max_n=20):
    for m in range(1, max_m+1):
        for n in range(1, max_n+1):
            banned = set()
            ok = True
            for _ in range(m*n):
                pos = mortal(banned)
                if pos in banned: ok = False; break
                banned.add(eternity(banned, pos))
            if not ok: return False, (m,n)
    return True, None
